        leave(date);
        await app.settle();
        await submitWithEnter();
        expect(app.path()).toBe('/co/datos');
        expect(document.activeElement).toBe(date);
        expect(describedText(date)).toContain(MESSAGE);
        expect(store().step1Output()).toBeNull();
      });
    }
  });

